import sys; sys.path.insert(0,'source')
import pydicom, os
from pathlib import Path
root = Path('source/pydicom/data')
hits=[]
for dp,_,fns in os.walk(root):
    for fn in fns:
        if not fn.endswith('.dcm'): continue
        fp = Path(dp)/fn
        try:
            ds = pydicom.dcmread(str(fp), stop_before_pixels=False, specific_tags=['PhotometricInterpretation','SamplesPerPixel','BitsAllocated'])
        except Exception:
            continue
        pi = getattr(ds,'PhotometricInterpretation',None)
        if pi and ('YBR' in str(pi) or str(pi)=='RGB') and getattr(ds,'SamplesPerPixel',1)>1:
            hits.append((str(fp),pi,getattr(ds,'BitsAllocated',None)))
for h in hits[:40]:
    print(h)
print('total color:', len(hits))
\"
